profiles=[]
def card(id,title,canon,confidence,pools,analysis,formula,avoid,exception='',source=None):
    profiles.append(dict(id=id,title=title,canon=canon.split('|') if canon else [],confidence=confidence,pools=pools.split('|') if pools else [],analysis=analysis,formula=formula,avoid=avoid,exception=exception,local_source=source or 'NAMES_OGNI_KINGS.md',proposal_status='analytical_proposal_not_new_canon'))
card('dangun','Люди: дангунцы','Иярдар|Ияр|Изудин|Аларк|Элютиль|Буболор|Волжин|Гинала|Халиса|Петра|Мирна','средняя для смешанного пула; низкая для одной этнической привязки','turkish|arabic_shared|mediterranean_shared|indic','Разнородный городской репертуар. Изудин напоминает имена с арабским компонентом ad-din, но точная этимология не установлена. Петра — реальное европейское имя; остальные формы нельзя автоматически объявлять арабскими, славянскими или персидскими. Дангун как торговый перекрёсток объясняет смесь лучше, чем единый национальный прототип.','Выбрать одну семейную традицию → взять целое реальное имя → при необходимости добавить известный дом отдельным элементом. Новые имена одной семьи брать из одного пула, если биография не объясняет смешение.','Не принуждать все имена начинаться на Из-/Ия-. Не превращать -дин в свободный суффикс и не сочинять его значение.','Решение о разнообразии дангунских имён записано в справочнике как авторское; это свидетельство документа, а не новая команда пользователя.')
card('brall','Люди: бралльцы','Миндер|Кирки|Харча|Вазар|Ашер|Сухарто|Лалур|Нана|Бельсава|Карна|Ид|Джахи','средняя; Сухарто даёт сильный отдельный якорь','indic|tibetan|turkish','Основной рабочий пул — Южная Азия, с отдельным яванско-индонезийским пластом. Мехул на странице расы имеет реальных индийских носителей, Сухарто — точный современный индонезийский антропоним. Нана распространено в нескольких культурах и само по себе ничего не доказывает. Тала/Сома/Нима допускают несколько объяснений. Тибетский подпул — предложение, не доказанное происхождение бралльцев.','Реальное имя, чаще 1–3 слога → бытовое прозвище по биографии → Баба только для почётного обращения, если статус персонажа его оправдывает.','Не давать всем яванские имена из-за одного Сухарто. Не определять пол по слову Баба. Не сочинять женское имя прибавлением -ва.','Индонезийский подпул пока не включён в стартовый банк: одного проверенного имени, уже занятого в каноне, недостаточно для разнообразного генератора.')
card('adaad','Люди: адаады','Карабалгун','низкая','turkish|mongolian','В книге надёжный пример — Карабалгун, причём имя описано как худдулинское. Страничные Кара’зул/Мара’са показывают собственную модель, но не позволяют доказать реальную национальную основу. Тюркские и монгольские имена пригодны как отдельные предложения, особенно для воспитанного в степи персонажа.','Выбрать: местное имя по модели страницы / реальное степное имя приёмного ребёнка / настоящее заимствованное имя. Апостроф не вставлять внутрь реального имени ради эффекта.','Не использовать Нармандах как обычное новое имя: это известное древнее имя и псевдоним Карабалгуна. Не считать пары с апострофом настоящими современными именами.','Самобытная местная форма и неизменённое современное реальное имя здесь не всегда совместимы. Если нужен строгий режим реальности, выбирать заимствование или степное воспитание.')
card('hanid','Люди: Ханид и Мигдаш','Абрам|Джараб|Гирджа|Арлан Изигдо|Ишита|Ниби|Дияла','низкая–средняя','indic|turkish|mediterranean_shared','Городской смешанный пул. Абрам даёт библейский пласт; Ишита и Гирджа напоминают южноазиатские формы, но сходство не доказывает пол или происхождение. Ниби несёт кровь джиннов, Дияла — полухуддулинка: происхождение и местная культура должны храниться отдельно.','Выбрать семейную культуру → целое имя → дом/семья по необходимости. Ханид и Мигдаш — региональные профили людей, а не дополнительные биологические расы.','Не выводить пол Ишиты из реального индийского имени Ishita; канонический персонаж — мужчина. Не присваивать всем горожанам одну этничность.')
card('ancient_humans','Люди Времени Королей','Мелозар|Охурозар|Фахат|Гулом|Итон|Тусус|Эктор|Ветамон|Куджин|Аегус|Му|Ло|Сабара','низкая–средняя','mediterranean_shared|arabic_shared|turkish','Смешанный архаизирующий репертуар. Эктор сближает с греческим Гектором; Гулом напоминает центральноазиатскую форму арабского غلام, но точное происхождение не подтверждено. Му/Ло не доказывают китайскую традицию. Королевские эпитеты — отдельная система.','Реальное имя из выбранного семейного пула + Король/Королева [понятия в родительном падеже], если персонаж действительно правитель.','Не использовать древние королевские имена как свободный запас; не добавлять каждому имени псевдогреческое -ус/-он.')
card('white_faith','Имена Белой веры и наречения','Иссидор|Весшарва|Эшер|Ишмал|Эльбир|Граар|Ахаб','средняя для религиозного слоя','mediterranean_shared|arabic_shared|turkish','Здесь виден сословный/религиозный репертуар поверх этнических культур. Иссидор напоминает Исидора, Ахаб — библейский антропоним, Ишмал — Исмаила. Эти сходства не означают единую расу и не устанавливают этимологию Весшарвы.','Родное имя либо реально употребляемое имя, выбранное при наречении → обращение отец/должность отдельно. Сохранять историю старого имени.','Не переносить церковный пул на всех людей и не считать любой титул личным именем.')
card('hudd_erh','Худдулины: эрх','Тэнгар|Нергуль|Кашурур|Матаас|Умбар|Хид|Аху|Алайгул|Ухэ|Мал’гул|Мах’Тара|Навча|Чанга','средняя','mongolian|turkish','Степной тюрко-монгольский спектр — наиболее полезная рабочая гипотеза. Наран-, дорг и общий репертуар р/г/х/ч на странице поддерживают её. -гул допускает тюркский gü(l), но также созвучен монгольским элементам; нельзя объявлять все -гул одним заимствованием. Тэнгар близок кругу Тенгри/Тэнгэр, но конкретная связь остаётся гипотезой.','Выбрать монгольское ИЛИ тюркское целое имя → род/кровь отдельной записью. Отслеживать пол по свидетельству конкретного имени, а не по окончанию.','Не склеивать турецкий корень с монгольским окончанием. Не считать -гул женским: Нергуль — мужчина. Не переносить личное имя Пепел на традиционную модель рождения.','Тэнгар → Пепел — смена/утрата имени; Пепел — особая биография, не общий суффиксный шаблон.')
card('hudd_sar','Худдулины: сар','Гогур’сар|Бегда’сар|Михтар’сар|Урх’сар|Химер’сар|Джаджа’сар|Силра’сар','средняя для степной основы; высокая для правила страницы/справочника','mongolian|turkish','Основу разумно брать из степного пула. ’сар — внутримировой маркер, а не доказательство татарской, монгольской или иной национальности. Он присоединяется к имени независимо от пола согласно записанному в справочнике решению.','Настоящее степное личное имя + ’сар. Отдельно хранить real_base и setting_full; вся полная форма не объявляется реальным современным именем.','Не использовать форму без ’сар для обычного сара в режиме сеттинга; не добавлять частицу дважды.','Сарим — полукровка и отдельный случай. Старые KB-карточки ещё называют его саром; более поздний справочник записывает авторское уточнение «Не Сар». Это конфликт версий, а не основание удалять старые сведения.')
card('hudd_omor','Худдулины: омор','Чаланга','низкая–средняя','mongolian','Надёжный книжный пример очень малочислен. На странице расы добавлены Чендоорг, Чинуук, Черга, Чамба. Это поддерживает фонетику ч/г/р и монгольский ориентир, но не обязательность буквы Ч и не североамериканский пул из-за Чинуука.','Целое степное имя с ч/г/р, если доступно → одиночное личное имя. При нехватке подходящих имён расширить проверенный банк, а не изобретать слоги.','Не объявлять каждое имя на Ч- оморским. Не использовать Чендорга, отца Пепла, как доказанного омора: его родство само по себе подрасу не устанавливает.','В текущем проверенном банке мало имён с Ч; временный подбор шире фонетического ориентира и помечен как предложение.')
card('hudd_mixed','Худдулины: смешанное происхождение','Сарим|Мазр|Дияла','низкая для отдельной системы','mongolian|turkish|mediterranean_shared','Это не самостоятельный национальный именник. Имя зависит от того, кто воспитывал ребёнка и кто его нарёк. Сарим показывает, что необычное имя может отражать исключение, но не задаёт модель всем полукровкам.','Культура воспитания → реальное имя её пула → личная история наречения. ’сар не добавлять автоматически.','Не создавать отдельный набор суффиксов «полукровок».')
card('mara_ash','Маракийцы: пепельные','Меток|Джамаар|А’за’ал','низкая для подрасы; средняя для пустынного стилистического ориентира','arabic_shared|turkish','Эти примеры взяты со страницы маракийцев, где не дана надёжная привязка каждого имени к пепельным. Джамаар напоминает современное Jamar и ряд арабских созвучий; А’за’ал архаизирует звучание. Нельзя считать это доказанным арабским именником или обязательным удвоением гласных.','Рабочее предложение: целые имена арабского/арабо-персидского круга, без искусственного удвоения букв. Подрасу хранить отдельно от культуры.','Не переносить черновое правило «всегда двойная гласная» в канон. В А’за’ал два апострофа: прежнее правило «только один» опровергается собственным примером.','Персидский подпул требует расширения проверенных современных носителей; не включён только на основании созвучия.')
card('mara_amber','Маракийцы: янтарные','Изия','низкая','turkish|arabic_shared','Изия прямо назван янтарным; одного имени недостаточно для своей этимологии. Шида — маракийка, но её подраса в использованном справочнике не установлена. Поэтому нельзя строить отдельный женский янтарный именник на Шиде.','Пока использовать общий маракийский/региональный пул → целое короткое реальное имя → семья отдельно. Более конкретный национальный подпул — авторское предложение.','Не выводить всех янтарных из еврейского/японского именника по одному созвучию Изии.')
card('dragmir','Драгмирцы','Саргон|Эль|Драгмир','средняя для месопотамского пласта; низкая для единой национальной системы','arabic_shared|turkish','Саргон — точное историческое месопотамское имя. Драгмир напоминает славянское сочетание -мир, но это эпоним создателя народа, а не рядовое имя. Эль имеет множество возможных созвучий. Смешение древнего и современного нельзя скрывать.','Для современных «настоящих» имён: целое засвидетельствованное имя близкого регионального пула + «из семьи [семья]». Для древних имён: отдельный исторический банк, без заявления о современной распространённости.','Не брать имена богов Мардук/Шамас как будто это повседневные современные личные имена. Не делать всех драгмирцев славянами из-за Драгмира.')
card('udr_urma','Удриши: урма','','нет книжной выборки для подрасы','indic|finnic_optional|mediterranean_shared','Отдельного набора имён урма в использованном материале нет. Южноазиатский короткий пул — рабочая экстраполяция общих удришских образцов; финский — только необязательный фонетический резерв с простыми слогами, не гипотеза о происхождении.','Выбрать короткое настоящее имя из одного утверждённого пула → клан при необходимости → игровое прозвище отдельно.','Не объявлять профиль урма восстановленным каноном; не вводить обязательную редупликацию всем удришам.')
card('udr_eril','Удриши: эрил','Кофу Ва’афна|Стафф|Сильная Рука','низкая','indic|finnic_optional|mediterranean_shared','Кофу короткое двусложное; Стафф резко отличается, Сильная Рука — прозвище. Мана и Мишмаш относятся к удришам, но не служат доказанными именами эрил. Японский, африканский или скандинавский пул по одному Кофу/Стафф был бы чрезмерным выводом.','Короткое целое реальное имя → клан отдельным словом (апостроф внутри имени клана сохранять) → прозвище по истории.','Не превращать Ва’афна в окончание личного имени. Не сокращать чужое реальное имя случайным обрезанием, если нужен засвидетельствованный вариант.')
card('udr_pyy','Удриши: пйюр-пйюр','Мишмаш','низкая','indic|finnic_optional|mediterranean_shared','Мишмаш и само название пйюр-пйюр дают игривость и повторение. Это фонетическое наблюдение, не конкретный реальный этнос. Редупликация встречается в разных языках; сама по себе не доказывает индонезийское, китайское или иное происхождение.','Строго реальное: целое короткое имя. В режиме сеттинга можно дать повторяемое прозвище по биографии; его отмечать как вымышленное.','Не удваивать любое имя и не объявлять результат реальным человеческим антропонимом.')
card('adj','Аджаиды','Аджар|Раджин|Алтун|Бараскус','средняя для смешанного индийско-тюркского ориентира','indic|turkish','Раджин сближается с южноазиатским кругом Rajan/Rajin, Алтун — с тюркским altun. Аджар не устанавливает этимологию без дополнительных свидетельств. Бараскус — древний король, отдельный легендарный слой.','Проверенное взрослое имя → детское имя лишь как засвидетельствованная краткая форма либо отдельное настоящее детское имя → имя дороги как биографический эпитет.','Не превращать мужское имя в женское автоматическим -а: существование мужской формы не доказывает женскую. Не называть произвольное сокращение настоящим именем.')
card('boros','Боросы','Нармандах|Дэр-Дэр|Тардэр|Амракчар','средняя; высокая для реальности Нармандаха','mongolian','Самый чёткий монгольский антропонимический якорь — Нармандах, имеющий современных реальных носителей. Остальная выборка допускает степной ориентир, но не доказывает монгольскую этимологию Тардэра или Амракчара. Последний — имя-титул.','Целое монгольское имя → отдельный клан/статус при наличии канона → краткое имя только как засвидетельствованный вариант или явно придуманное прозвище. Женский пул — реальный монгольский, но его соответствие бороскам пока авторское предложение.','Не использовать Нармандах снова; не изобретать женские имена на -дэр-а. Не переносить PF2e-правило шипящих с конца на весь народ.','В материале не найдены женские канонические имена боросов; это ограничение анализа, не утверждение об отсутствии имён у женщин народа.')
card('jabari','Джабари','Барабалду-гуль-да-дар-гадар-дан|Барбан|Руздо|Джабаррах’Коатамаранг-Груллтоба Малахит-Карра’Апу|Кхума','низкая для национального прототипа; высокая для многосоставности образцов','indic|tibetan|mongolian','Длинная церемониальная форма и короткое имя для общения — установленное различие. Южноазиатские, тибетские и монгольские длинные имена могут помочь структурно; назвать джабари конкретным реальным народом нельзя. Полный авторский женский образец не совпадает с краткими переводными именами страницы.','Для требования настоящего имени выбирать реально употребляемое короткое имя для людей. Полную родную форму хранить отдельно как форму ЭНОА и конструировать только с авторскими значениями компонентов.','Не клеить случайные санскритские/тибетские корни, не выдавать смесь за настоящую традицию. Не делать «Нежный Гром» автоматически женским личным именем.','Строго настоящая современная полная форма по имеющейся формуле не восстановлена. Конструктор даёт настоящее имя общения; церемониальный именник требует утверждения словаря.')
card('vetu_cycle','Вету: имена Цикла','Ти’Чан|Кса’Оточ|Ч’Кик|Ча’Каб|К’Шаакх','средняя для майяского стилистического пласта; низкая для реальной этимологии','','На странице видны чан/кик/каб/оточь, гортанные разрывы и образная структура. Это напоминает майяские языки; царские имена с Chan и K’inich действительно засвидетельствованы. Но сходство не подтверждает значения каждого слога страницы и не делает схему «камень + знак» аутентичной майяской традицией.','В режиме канона: разрешённый каменный префикс + разрешённый знак из таблицы сайта; значения брать только с сайта. Пол не влияет. В строгом режиме реальных современных имён эта модель не выполняется автоматически.','Не переводить слоги на память. Не смешивать майя и науатль из-за общего «мезоамериканского» впечатления. Не выдавать царское имя древности за повседневное современное.','Для настоящего современного имени выбрать биографически объяснённую форму изгнанника, то есть профиль vetu_exile. Native-генератор Цикла сознательно даёт форму сеттинга.',source='content/dnd5e/races/vetu.md, nameData')
card('vetu_exile','Вету: изгнанники','Хагах|Могой','низкая','mongolian|turkish|arabic_shared','Книжные имена относятся к жизни вне Цикла по зафиксированному в справочнике объяснению. Могой напоминает монгольское могой «змея», но словарное созвучие не доказывает, что это реальное личное имя. Хагах не задаёт национальный пул.','Культура, где изгнанник вырос/живёт → реальное имя её пула; можно отдельно сохранить прежнее имя Цикла.','Не использовать Хагаха и Могоя как подтверждение правила камней и знаков; не считать всякое монгольское слово личным именем.')
card('morhor','Морхоры','Абракс|Анахур|Тимурзид|Эмефеюс|Эдр’а','низкая–средняя','turkish|mediterranean_shared','Иранско-центральноазиатское и греко-эллинистическое звучание сочетаются: Тимурзид напоминает Тимур и имена/формы с -зид, Эмефеюс — греческое оформление, Абракс — созвучие Абраксасу. Это аналитические параллели, не установленные этимологии. Пуруш — первосущность, исключена из обычной выборки.','Выбрать одну традицию для семьи/Спирали → целое настоящее имя → отдельный статус. Женские формы выбирать по независимому реальному свидетельству.','Не объявлять -кс/-ур/-еюс обязательными и не лепить их к любому корню. Не устанавливать женское окончание ’а по единственной Эдр’а.','Современный персидский подпул обозначен как направление расширения, но не наполнен непроверенными именами. Иранские и тюркские имена не считать одной языковой традицией.')
card('ehor','Эхор’нуры','Ятх’У|Ша’Эннур','очень низкая','indic|tibetan','Ятх’У — книжный пример; Ша’Эннур — образец, записанный в справочнике как авторский. Оба поддерживают разрыв внутри формы, но не доказывают конкретный реальный этнос. Индийско-тибетский пул выбран как рабочее предложение по общему звучанию, не по числу рук/мистике народа.','Строго настоящее: целое заимствованное имя с объяснённой культурой наречения. Родное: только канонический образец и отдельно утверждённая схема, без заявления о реальной национальной традиции.','Не объявлять апостроф обязательным всем эхорам по двум примерам. Не делить реальные индийские имена апострофом.')
card('oyrdug','Ойрдуги','','нет надёжных именованных представителей','turkish|indic|mediterranean_shared','Страница сообщает, что мужские и женские имена пока не зафиксированы. Поэтому собственного национального пула восстановить нельзя. Безопасное рабочее решение — местная культура воспитания/наречения, отдельная от Двойной Искры.','Выбрать культуру персонажа → настоящее имя её пула → эпитет стигматы только если он нужен в биографии.','Не объявлять нефрит или Лабиринт доказательством китайской, индийской либо другой этничности.',source='content/dnd5e/races/oyrdugi.md')
card('kobold','Кобольды','Гуг|Хрип|Пуп|Тыть|Мемек|Джуга|Кир-кир|Ша’ша|Дагага','высокая для правила страницы; нет книжной выборки','finnic_optional|mediterranean_shared','Примеры страницы — звукоподражательные, иногда повторные. Это собственная модель ЭНОА, а не установленный национальный именник. Слово «кобольд» не делает имена германскими. Финский короткий пул — только добровольный источник настоящих заимствованных имён.','Родное: первый звук/клановое прозвище по правилу страницы, отмеченное как вымысел. Строго реальное: целое короткое имя, принятое при контакте с другой культурой.','Не представлять Гуг/Хрип/Тыть как настоящие современные имена без свидетельства; не объявлять повторение доказательством какого-либо этноса.',source='content/dnd5e/races/koboldy.md')
card('chotgor','Чотгоры','','высокая для отсутствия имени по традиции','','Норма страницы — не получать имён. Поэтому честный конструктор должен уметь возвращать отсутствие личного имени. Национальный пул имён здесь не выводится.','name = null; отдельное уникальное описание/обращение по месту, роли или событию. Если персонаж позднее наречён другим народом — использовать профиль нарекателя и записать исключение.','Не создавать обязательный ряд мужских и женских имён вопреки безымянности.',source='content/dnd5e/races/chotgory.md')
card('samagh','Самагхи','Хрун','низкая для родного пула; высокая для схемы страницы','indic|turkish|mediterranean_shared','Страница прямо задаёт заимствование у жителей поверхности с -га/-гха/-гаг. Национальный пул определяется донором. Хрун не соответствует этой схеме; причина не установлена, нельзя молча назвать его сокращением.','Реальное имя донора + отдельно сохранённая приспособленная форма с -га/-гха/-гаг. Почётное Баба отдельно.','Не выдавать полную адаптированную форму за реально употребляемое человеческое имя. Не придумывать этимологию Хруна.','Строгий режим возвращает настоящий донорский антропоним; native-форма помечается как форма сеттинга.')
card('virmborn','Вирморождённые','Круштервор','низкая для национальной атрибуции; высокая для артикуляции на странице','turkish','На странице запрещены п/б/м, указаны рычащие сочетания и много р. Это артикуляционный фильтр, не указание на германский или славянский этнос. Одного Круштервора мало для установления происхождения. Реальные турецкие имена позволяют подобрать часть форм без запрещённых звуков.','Реальное имя → исключить п/б/м → предпочтение р/г/к/т/х и закрытым слогам. Женские окончания «выдох огня» пока не формализованы надёжно; не вводить выдуманное -эша.','Не брать Бруно/Рагнар/Рихард лишь из-за «драконьего» ощущения без проверки. Не менять буквы в настоящем имени для прохождения фильтра.','В CLI применяется только твёрдо описанный запрет п/б/м; предпочтение р и женская фонетика остаются ручной оценкой.',source='content/dnd5e/races/virmorozhdennye.md')
card('elor','Элорцы / Вар’Элор','Садал|Мидал|Зумрат|Ум|Завлон|Элор','низкая','turkish|mediterranean_shared','Садал/Мидал показывают родственное созвучие; Зумрат напоминает ряд восточных форм, Завлон — библейское созвучие. Единой традиции это не устанавливает. Ни краткость Ум, ни рифма близнецов не доказывают китайские/корейские корни.','Одна семейная реальная традиция → целые настоящие имена. Для близнецов можно выбрать созвучные уже существующие имена, не создавая искусственные пары. Императорский порядковый титул отдельно.','Не превращать -дал в продуктивный суффикс всех элорцев. Не выводить пол или братство по буквам без контекста.')
card('meridir','Меридиры','Агранор|Цам','очень низкая','tibetan|mediterranean_shared','Два имени резко различаются. Цам созвучен названию буддийской ритуальной традиции, но это не доказывает реальность личного имени или происхождение народа. Агранор может быть авторским фэнтезийным именем; доказательств реального этноса нет.','Настоящее имя выбирать по культуре наречения/прошлой жизни персонажа; тибетский подпул — необязательное стилистическое предложение.','Не считать ритуальный термин автоматически антропонимом. Не объявлять всех меридиров тибетцами.')
card('dragons','Драконы и вирмы','Мардук|Хаар|Закит|Изрид','низкая','turkish|arabic_shared','Мардук — известное месопотамское божество, поэтому это мифологический якорь, но не ряд современных личных имён. Остальные примеры не устанавливают национальную систему.','Для требования настоящего имени — целый антропоним выбранной культуры как имя общения; истинное имя/титул хранить отдельно. Если переносить артикуляцию вирморождённых на самих вирмов, отдельно обозначить это как допущение.','Не считать теонимы обычными именами живых людей и не переносить все правила потомков на драконов автоматически.')
card('ogre','Огры','Отч','очень низкая','turkish|mediterranean_shared','Одно очень короткое имя не позволяет восстановить собственный национальный именник. Короткость — только наблюдение.','Культура проживания → короткое целое реальное имя, если важно требование реальности; прозвище отдельно.','Не приписывать этнос или обязательный согласный по одному Отчу.')
card('colossus','Колоссы','Эквинтус','очень низкая','mediterranean_shared','Эквинтус напоминает латинский Quintus, но не совпадает с ним. Римский ориентир — стилистическое предложение, а не установленное происхождение.','Реальное латинское/средиземноморское имя, подтверждённое отдельным источником; текущий банк даёт современный средиземноморский резерв.','Не считать приставку Э- способом превращать все латинские имена в реальные имена колоссов.')
card('mephit','Мефиты','Меппо|Пеппо|Деппо','низкая для этнического пула; средняя для локальной семейной рифмы','mediterranean_shared','Рифма трёх братьев — сильное наблюдение конкретной группы. Итальянское ощущение -ппо/-о может помочь стилистически, но не доказывает итальянское происхождение всех мефитов.','Реальное короткое имя; для родственников выбирать уже существующие созвучные формы. Новую рифму-прозвище отмечать как придуманную.','Не подставлять любую согласную вместо М-/П-/Д- и не выдавать результат за настоящий итальянский антропоним.')

pages=json.loads((ROOT/'tmp/name_analysis/pages.json').read_text(encoding='utf-8'))
vk=json.loads((ROOT/'app/data/loreUzlyVremyaKoroley.generated.json').read_text(encoding='utf-8'))
kings=[]
for chapter in vk['chapters']:
    for bi,block in enumerate(chapter['blocks']):
        for pi,paragraph in enumerate(block.get('paragraphs',[])):
            kings.append({'chapter':chapter['number'],'block':bi,'paragraph':pi,'text':paragraph})
kb=json.loads((KB/'campaign_knowledge.json').read_text(encoding='utf-8'))
registry={}
def reserve(name,source,kind='reserved_source_name'):
    if not name or len(name)>200:return
    key=norm(name)
    if not key:return
    row=registry.setdefault(key,{'normalized':key,'forms':[],'sources':[],'kind':kind})
    if name not in row['forms']:row['forms'].append(name)
